<style>
  .budget-selector-container {
    background-image: url("/images/beach-background.svg");
    height: 714px;
    display: flex;
    flex-direction: column;
    align-items: center;
  }
  .budget-selector-header {
    padding: 72px 0 16px;
    display: flex;
    justify-content: center;
    gap: 16px;
    align-items: center;
  }
  .budget-selector-header > span {
    color: #fff;
    text-align: center;
    font-size: 24px;
    font-weight: 700;
    text-transform: capitalize;
  }

  .desktop {
    display: flex;
    justify-content: center;
  }

  .mobile {
    display: none;
  }

  @media only screen and (width <= 720px) {
    .desktop {
      display: none;
    }
    .mobile {
      display: flex;
      justify-content: center;
    }
    .budget-selector-header {
      padding: 40px 0 16px;
    }
  }
</style>
